<script>
  import { onMount } from 'svelte';
  import { projectStore, materialStore, uiStore, authStore } from '../stores/index.js';
  import { 
    materialsApi, 
    inboundRecordsApi, 
    outboundRecordsApi,
    categoriesApi 
  } from '../services/database.js';
  import { canInbound, canOutbound, canCreateProject, isAdmin, canEditInbound, canEditOutbound } from '../constants/roles.js';
  import DataTable from '../components/DataTable.svelte';
  import * as XLSX from 'xlsx';

  export let params = {};

  let projectId = null;
  let viewType = null;
  let categoryId = null;
  let project = null;
  let category = null;
  let materials = [];
  let records = [];
  let isLoading = true;
  let role = null;

  // Form state
  let showAddForm = false;
  let formData = {
    name: '',
    specification: '',
    material_type: '',
    description: '',
    unit: '',
    quantity: 0,
    date: new Date().toISOString().split('T')[0],
    batch_no: '',
    remarks: ''
  };

  // Edit modal state
  let showEditModal = false;
  let editingRecord = null;
  let editFormData = {
    quantity: 0,
    date: '',
    batch_no: '',
    remarks: ''
  };

  // Pagination state
  let currentPage = 1;
  let pageSize = 20;
  const pageSizeOptions = [10, 20, 50, 100];

  // 计算当前显示的数据
  $: displayData = viewType === 'remaining' ? materials : records;
  $: totalItems = displayData.length;
  $: totalPages = Math.ceil(totalItems / pageSize);
  $: paginatedData = displayData.slice((currentPage - 1) * pageSize, currentPage * pageSize);
  $: startIndex = (currentPage - 1) * pageSize + 1;
  $: endIndex = Math.min(currentPage * pageSize, totalItems);

  // 切换视图时重置分页
  $: if (viewType || categoryId) {
    currentPage = 1;
  }

  // Table columns based on view type
  $: columns = getColumns(viewType);

  $: {
    // When route params change, close form and reset
    const prevProjectId = projectId;
    const prevViewType = viewType;
    const prevCategoryId = categoryId;
    
    projectId = params.projectId;
    viewType = params.viewType;
    categoryId = params.categoryId || null;
    
    // Close form when switching views or categories
    if (prevProjectId !== projectId || prevViewType !== viewType || prevCategoryId !== categoryId) {
      if (showAddForm) {
        showAddForm = false;
        resetForm();
      }
    }
    
    loadData();
  }

  authStore.subscribe(state => {
    role = state.role;
  });

  projectStore.subscribe(state => {
    if (projectId) {
      project = state.projects.find(p => p.$id === projectId);
      if (project && categoryId) {
        category = project.categories?.find(c => c.$id === categoryId);
      }
    }
  });

  function getColumns(type) {
    const baseColumns = [
      { key: 'name', label: '名称', sortable: true, filterable: true },
      { key: 'specification', label: '规格型号', sortable: true, filterable: true },
      { key: 'material_type', label: '材质', sortable: true, filterable: true },
      { key: 'description', label: '材料描述', sortable: false, filterable: true },
      { key: 'unit', label: '单位', sortable: true, filterable: true }
    ];

    if (type === 'inbound') {
      return [
        ...baseColumns,
        { key: 'quantity', label: '数量', sortable: true, type: 'number' },
        { key: 'arrival_date', label: '到货时间', sortable: true, type: 'date' },
        { key: 'batch_no', label: '到货单编号', sortable: true, filterable: true },
        { key: 'remarks', label: '备注', sortable: false }
      ];
    } else if (type === 'outbound') {
      return [
        ...baseColumns,
        { key: 'quantity', label: '数量', sortable: true, type: 'number' },
        { key: 'outbound_date', label: '出库时间', sortable: true, type: 'date' },
        { key: 'outbound_no', label: '出库单编号', sortable: true, filterable: true },
        { key: 'remarks', label: '备注', sortable: false }
      ];
    } else {
      // remaining
      return [
        ...baseColumns,
        { key: 'total_inbound', label: '入库总量', sortable: true, type: 'number' },
        { key: 'total_outbound', label: '出库总量', sortable: true, type: 'number' },
        { key: 'remaining_qty', label: '剩余数量', sortable: true, type: 'number', highlight: true }
      ];
    }
  }

  async function loadData() {
    if (!projectId || !viewType) return;
    
    isLoading = true;
    materials = [];
    records = [];

    try {
      if (viewType === 'remaining') {
        // For remaining view, show aggregated materials
        const result = categoryId 
          ? await materialsApi.listByCategory(categoryId)
          : await materialsApi.listByProject(projectId);
        
        materials = result.data || [];
      } else if (viewType === 'inbound') {
        // For inbound, show records
        if (categoryId) {
          const result = await inboundRecordsApi.listByCategory(categoryId);
          records = result.data || [];
        }
      } else if (viewType === 'outbound') {
        // For outbound, show records
        if (categoryId) {
          const result = await outboundRecordsApi.listByCategory(categoryId);
          records = result.data || [];
        }
      }
    } catch (error) {
      console.error('Load data error:', error);
      uiStore.showNotification('加载数据失败', 'error');
    } finally {
      isLoading = false;
    }
  }

  function getViewTypeLabel(type) {
    const labels = {
      inbound: '入库材料汇总',
      outbound: '出库材料汇总',
      remaining: '剩余材料汇总'
    };
    return labels[type] || type;
  }

  function toggleAddForm() {
    showAddForm = !showAddForm;
    if (showAddForm) {
      resetForm();
    }
  }

  function resetForm() {
    formData = {
      name: '',
      specification: '',
      material_type: '',
      description: '',
      unit: '',
      quantity: 0,
      date: new Date().toISOString().split('T')[0],
      batch_no: '',
      remarks: ''
    };
  }

  async function handleSubmit() {
    // === 基础字段验证 ===
    if (!formData.name || !formData.name.trim()) {
      uiStore.showNotification('请输入材料名称', 'error');
      return;
    }

    if (!formData.specification || !formData.specification.trim()) {
      uiStore.showNotification('请输入规格型号', 'error');
      return;
    }

    if (!formData.material_type || !formData.material_type.trim()) {
      uiStore.showNotification('请输入材质', 'error');
      return;
    }

    // === 数量验证 ===
    const qty = parseFloat(formData.quantity);
    
    if (isNaN(qty)) {
      uiStore.showNotification('请输入有效的数量', 'error');
      return;
    }

    if (qty <= 0) {
      uiStore.showNotification('数量必须大于0', 'error');
      return;
    }

    if (qty > 999999) {
      uiStore.showNotification('数量不能超过999999', 'error');
      return;
    }

    // === 日期验证 ===
    if (!formData.date) {
      uiStore.showNotification('请选择日期', 'error');
      return;
    }

    uiStore.showLoading(viewType === 'inbound' ? '入库中...' : '出库中...');
    try {
      // 查找或创建材料
      const materialResult = await materialsApi.findOrCreate(projectId, categoryId, {
        name: formData.name.trim(),
        specification: formData.specification.trim(),
        material_type: formData.material_type.trim(),
        description: formData.description?.trim() || '',
        unit: formData.unit?.trim() || ''
      });

      if (materialResult.error) {
        throw materialResult.error;
      }

      const materialId = materialResult.data.$id;

      // 创建记录
      if (viewType === 'inbound') {
        // === 入库记录 ===
        const result = await inboundRecordsApi.create(projectId, categoryId, materialId, {
          quantity: qty,
          arrival_date: formData.date,
          batch_no: formData.batch_no?.trim() || '',
          remarks: formData.remarks?.trim() || ''
        });

        if (result.error) {
          throw result.error;
        }
        
        uiStore.showNotification(
          `入库成功！材料：${formData.name}，数量：${qty}${formData.unit || ''}`, 
          'success'
        );
      } else if (viewType === 'outbound') {
        // === 出库记录 ===
        const result = await outboundRecordsApi.create(projectId, categoryId, materialId, {
          quantity: qty,
          outbound_date: formData.date,
          outbound_no: formData.batch_no?.trim() || '',
          remarks: formData.remarks?.trim() || ''
        });

        if (result.error) {
          // 出库失败（库存不足等）
          throw result.error;
        }
        
        uiStore.showNotification(
          `出库成功！材料：${formData.name}，数量：${qty}${formData.unit || ''}`, 
          'success'
        );
      }

      // 成功后清理
      showAddForm = false;
      resetForm();
      await loadData();
      
    } catch (error) {
      console.error('Submit error:', error);
      
      // 详细的错误处理
      let errorMessage = '操作失败';
      
      if (error instanceof Error) {
        errorMessage = error.message;
      } else if (typeof error === 'string') {
        errorMessage = error;
      } else if (error?.message) {
        errorMessage = error.message;
      } else if (error?.toString) {
        errorMessage = error.toString();
      }
      
      // 显示错误，保持表单打开以便修改
      uiStore.showNotification(errorMessage, 'error');
    } finally {
      uiStore.hideLoading();
    }
  }

  // Excel Import
  let fileInput;

  function handleImportClick() {
    fileInput.click();
  }

  async function handleFileUpload(event) {
    const file = event.target.files[0];
    if (!file) return;

    uiStore.showLoading('解析Excel文件中...');
    try {
      const data = await file.arrayBuffer();
      const workbook = XLSX.read(data);
      const sheetName = workbook.SheetNames[0];
      const worksheet = workbook.Sheets[sheetName];
      const jsonData = XLSX.utils.sheet_to_json(worksheet);

      if (jsonData.length === 0) {
        uiStore.showNotification('Excel文件为空', 'warning');
        uiStore.hideLoading();
        return;
      }

      // 大量数据提示
      if (jsonData.length > 100) {
        uiStore.showLoading(`正在导入 ${jsonData.length} 条数据，请耐心等待...`);
      }

      let successCount = 0;
      let errorCount = 0;
      const batchSize = 10; // 每批处理10条，避免请求过快

      // 辅助函数：从多个可能的列名中获取值
      const getField = (row, ...keys) => {
        for (const key of keys) {
          if (row[key] !== undefined && row[key] !== null && row[key] !== '') {
            return row[key];
          }
        }
        return null;
      };

      // 分批处理
      for (let i = 0; i < jsonData.length; i += batchSize) {
        const batch = jsonData.slice(i, Math.min(i + batchSize, jsonData.length));
        
        // 更新进度
        uiStore.showLoading(`导入中... ${Math.min(i + batchSize, jsonData.length)}/${jsonData.length}`);

        // 处理当前批次
        for (const row of batch) {
          try {
            // 获取材料信息（支持多种列名）
            const name = getField(row, '名称', 'name', '材料名称', '物料名称');
            const specification = getField(row, '规格型号', 'specification', '规格', '型号');
            const materialType = getField(row, '材质', 'material_type', '材料类型', '类型');
            
            // 必填字段验证
            if (!name || !specification || !materialType) {
              errorCount++;
              continue;
            }

            const materialResult = await materialsApi.findOrCreate(projectId, categoryId, {
              name: String(name).trim(),
              specification: String(specification).trim(),
              material_type: String(materialType).trim(),
              description: String(getField(row, '材料描述', 'description', '描述', '备注') || '').trim(),
              unit: String(getField(row, '单位', 'unit') || '').trim()
            });

            if (materialResult.data) {
              const qty = parseFloat(getField(row, '数量', 'quantity', '入库数量', '出库数量') || 0);
              if (qty > 0) {
                if (viewType === 'inbound') {
                  // 支持多种日期列名
                  const dateStr = getField(row, 
                    '到货时间', '入库时间', '到货日期', '入库日期', 
                    'arrival_date', 'date', '日期', '时间'
                  );
                  
                  await inboundRecordsApi.create(projectId, categoryId, materialResult.data.$id, {
                    quantity: qty,
                    arrival_date: dateStr ? String(dateStr) : new Date().toISOString().split('T')[0],
                    batch_no: String(getField(row, '到货单编号', '入库单编号', 'batch_no', '单据编号', '编号') || '').trim(),
                    remarks: String(getField(row, '备注', 'remarks', '说明') || '').trim()
                  });
                  successCount++;
                } else if (viewType === 'outbound') {
                  // 出库也支持多种列名
                  const dateStr = getField(row,
                    '出库时间', '出库日期', 'outbound_date', 'date', '日期', '时间'
                  );
                  
                  await outboundRecordsApi.create(projectId, categoryId, materialResult.data.$id, {
                    quantity: qty,
                    outbound_date: dateStr ? String(dateStr) : new Date().toISOString().split('T')[0],
                    outbound_no: String(getField(row, '出库单编号', 'outbound_no', '单据编号', '编号') || '').trim(),
                    remarks: String(getField(row, '备注', 'remarks', '说明') || '').trim()
                  });
                  successCount++;
                }
              } else {
                // 只创建材料，不创建出入库记录
                successCount++;
              }
            }
          } catch (rowError) {
            console.warn('Import row error:', rowError);
            errorCount++;
          }
        }

        // 小延迟，避免请求过于密集
        if (i + batchSize < jsonData.length) {
          await new Promise(resolve => setTimeout(resolve, 100));
        }
      }

      // 显示导入结果
      if (errorCount === 0) {
        uiStore.showNotification(`成功导入 ${successCount} 条数据`, 'success');
      } else {
        uiStore.showNotification(`导入完成: 成功 ${successCount} 条，失败 ${errorCount} 条`, 'warning');
      }
      
      loadData();
    } catch (error) {
      console.error('Import error:', error);
      uiStore.showNotification('导入失败: ' + error.message, 'error');
    } finally {
      uiStore.hideLoading();
    }

    // Reset file input
    event.target.value = '';
  }

  // Excel Export
  function handleExport() {
    const dataToExport = viewType === 'remaining' ? materials : records;
    
    if (dataToExport.length === 0) {
      uiStore.showNotification('没有数据可导出', 'warning');
      return;
    }

    // Create worksheet
    const ws = XLSX.utils.json_to_sheet(dataToExport.map(item => {
      const row = {};
      columns.forEach(col => {
        row[col.label] = item[col.key] || '';
      });
      return row;
    }));

    // Create workbook
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, getViewTypeLabel(viewType));

    // Download
    const fileName = `${project?.name || 'export'}_${getViewTypeLabel(viewType)}_${new Date().toISOString().split('T')[0]}.xlsx`;
    XLSX.writeFile(wb, fileName);
  }

  // Create Category
  let showCreateCategory = false;
  let newCategoryName = '';

  async function handleCreateCategory() {
    if (!newCategoryName.trim()) return;

    uiStore.showLoading('创建分类中...');
    try {
      const result = await categoriesApi.create(projectId, newCategoryName);
      if (result.error) throw result.error;

      uiStore.showNotification('分类创建成功', 'success');
      showCreateCategory = false;
      newCategoryName = '';
      
      // Reload projects to update sidebar
      window.location.reload();
    } catch (error) {
      console.error('Create category error:', error);
      uiStore.showNotification('创建失败', 'error');
    } finally {
      uiStore.hideLoading();
    }
  }

  // =============================================
  // Edit & Delete Record Functions
  // =============================================
  
  // 检查当前用户是否可以编辑记录
  function canEditCurrentRecord() {
    if (viewType === 'inbound') {
      return canEditInbound(role);
    } else if (viewType === 'outbound') {
      return canEditOutbound(role);
    }
    return false;
  }

  // 打开编辑模态框
  function openEditModal(record) {
    editingRecord = record;
    if (viewType === 'inbound') {
      editFormData = {
        quantity: record.quantity,
        date: record.arrival_date || '',
        batch_no: record.batch_no || '',
        remarks: record.remarks || ''
      };
    } else if (viewType === 'outbound') {
      editFormData = {
        quantity: record.quantity,
        date: record.outbound_date || '',
        batch_no: record.outbound_no || '',
        remarks: record.remarks || ''
      };
    }
    showEditModal = true;
  }

  // 关闭编辑模态框
  function closeEditModal() {
    showEditModal = false;
    editingRecord = null;
    editFormData = {
      quantity: 0,
      date: '',
      batch_no: '',
      remarks: ''
    };
  }

  // 保存编辑
  async function handleSaveEdit() {
    if (!editingRecord) return;

    const qty = parseFloat(editFormData.quantity);
    if (isNaN(qty) || qty <= 0) {
      uiStore.showNotification('请输入有效的数量', 'error');
      return;
    }

    uiStore.showLoading('保存中...');
    try {
      let result;
      if (viewType === 'inbound') {
        result = await inboundRecordsApi.update(editingRecord.$id, editingRecord.material_id, {
          quantity: qty,
          arrival_date: editFormData.date,
          batch_no: editFormData.batch_no,
          remarks: editFormData.remarks
        });
      } else if (viewType === 'outbound') {
        result = await outboundRecordsApi.update(editingRecord.$id, editingRecord.material_id, {
          quantity: qty,
          outbound_date: editFormData.date,
          outbound_no: editFormData.batch_no,
          remarks: editFormData.remarks
        });
      }

      if (result?.error) {
        throw result.error;
      }

      uiStore.showNotification('修改成功', 'success');
      closeEditModal();
      await loadData();
    } catch (error) {
      console.error('Update error:', error);
      uiStore.showNotification('修改失败: ' + (error.message || '未知错误'), 'error');
    } finally {
      uiStore.hideLoading();
    }
  }

  // 删除记录
  async function handleDeleteRecord(record) {
    const confirmMsg = viewType === 'inbound' 
      ? `确定删除这条入库记录吗？\n材料: ${record.name}\n数量: ${record.quantity}`
      : `确定删除这条出库记录吗？\n材料: ${record.name}\n数量: ${record.quantity}`;
    
    if (!confirm(confirmMsg)) return;

    uiStore.showLoading('删除中...');
    try {
      let result;
      if (viewType === 'inbound') {
        result = await inboundRecordsApi.delete(record.$id, record.material_id);
      } else if (viewType === 'outbound') {
        result = await outboundRecordsApi.delete(record.$id, record.material_id);
      }

      if (result?.error) {
        throw result.error;
      }

      uiStore.showNotification('删除成功', 'success');
      await loadData();
    } catch (error) {
      console.error('Delete error:', error);
      uiStore.showNotification('删除失败: ' + (error.message || '未知错误'), 'error');
    } finally {
      uiStore.hideLoading();
    }
  }

  // =============================================
  // Pagination Functions
  // =============================================
  function goToPage(page) {
    if (page >= 1 && page <= totalPages) {
      currentPage = page;
    }
  }

  function changePageSize(newSize) {
    pageSize = newSize;
    currentPage = 1; // 重置到第一页
  }

  function getVisiblePages() {
    const pages = [];
    const maxVisible = 5;
    
    if (totalPages <= maxVisible) {
      for (let i = 1; i <= totalPages; i++) {
        pages.push(i);
      }
    } else {
      // 始终显示第一页
      pages.push(1);
      
      let start = Math.max(2, currentPage - 1);
      let end = Math.min(totalPages - 1, currentPage + 1);
      
      if (currentPage <= 3) {
        end = Math.min(4, totalPages - 1);
      }
      if (currentPage >= totalPages - 2) {
        start = Math.max(2, totalPages - 3);
      }
      
      if (start > 2) pages.push('...');
      
      for (let i = start; i <= end; i++) {
        pages.push(i);
      }
      
      if (end < totalPages - 1) pages.push('...');
      
      // 始终显示最后一页
      if (totalPages > 1) pages.push(totalPages);
    }
    
    return pages;
  }
</script>

<div class="material-list">
  <!-- Breadcrumb -->
  <div class="breadcrumb">
    <span class="crumb">{project?.name || '项目'}</span>
    <span class="separator">/</span>
    <span class="crumb">{getViewTypeLabel(viewType)}</span>
    {#if category}
      <span class="separator">/</span>
      <span class="crumb active">{category.name}</span>
    {/if}
  </div>

  <!-- Toolbar -->
  <div class="toolbar">
    <div class="toolbar-left">
      {#if categoryId && viewType !== 'remaining'}
        {#if (viewType === 'inbound' && canInbound(role)) || (viewType === 'outbound' && canOutbound(role))}
          <button class="btn btn-primary" on:click={toggleAddForm}>
            {showAddForm ? '取消' : '+ 新增记录'}
          </button>
          <button class="btn btn-secondary" on:click={handleImportClick}>
            📥 导入Excel
          </button>
          <input 
            type="file" 
            accept=".xlsx,.xls" 
            bind:this={fileInput}
            on:change={handleFileUpload}
            style="display: none;"
          />
        {/if}
      {/if}
      {#if viewType === 'inbound' && !categoryId && canCreateProject(role)}
        <button class="btn btn-primary" on:click={() => showCreateCategory = true}>
          + 新建分类
        </button>
      {/if}
    </div>
    <div class="toolbar-right">
      <button class="btn btn-outline" on:click={handleExport}>
        📤 导出Excel
      </button>
    </div>
  </div>

  <!-- Add Form -->
  {#if showAddForm && categoryId}
    <div class="add-form">
      <h3>{viewType === 'inbound' ? '新增入库记录' : '新增出库记录'}</h3>
      <div class="form-grid">
        <div class="form-group">
          <label>名称 *</label>
          <input 
            type="text" 
            bind:value={formData.name} 
            placeholder="材料名称"
            required
            maxlength="100"
          />
        </div>
        <div class="form-group">
          <label>规格型号 *</label>
          <input 
            type="text" 
            bind:value={formData.specification} 
            placeholder="如: DN400 SCH10"
            required
            maxlength="100"
          />
        </div>
        <div class="form-group">
          <label>材质 *</label>
          <input 
            type="text" 
            bind:value={formData.material_type} 
            placeholder="如: S31803"
            required
            maxlength="50"
          />
        </div>
        <div class="form-group">
          <label>材料描述</label>
          <input 
            type="text" 
            bind:value={formData.description}
            maxlength="500"
          />
        </div>
        <div class="form-group">
          <label>单位</label>
          <input 
            type="text" 
            bind:value={formData.unit} 
            placeholder="如: 米、个"
            maxlength="20"
          />
        </div>
        <div class="form-group">
          <label>数量 *</label>
          <input 
            type="number" 
            bind:value={formData.quantity} 
            min="1" 
            max="999999"
            step="1"
            required
            placeholder="请输入大于0的数量"
          />
        </div>
        <div class="form-group">
          <label>{viewType === 'inbound' ? '到货时间' : '出库时间'}</label>
          <input type="date" bind:value={formData.date} />
        </div>
        <div class="form-group">
          <label>{viewType === 'inbound' ? '到货单编号' : '出库单编号'}</label>
          <input type="text" bind:value={formData.batch_no} />
        </div>
        <div class="form-group full-width">
          <label>备注</label>
          <input type="text" bind:value={formData.remarks} />
        </div>
      </div>
      <div class="form-actions">
        <button class="btn btn-primary" on:click={handleSubmit}>保存</button>
        <button class="btn btn-secondary" on:click={toggleAddForm}>取消</button>
      </div>
    </div>
  {/if}

  <!-- Create Category Modal -->
  {#if showCreateCategory}
    <div class="modal-overlay" on:click={() => showCreateCategory = false} on:keydown={(e) => e.key === 'Escape' && (showCreateCategory = false)} role="button" tabindex="-1">
      <div class="modal" on:click|stopPropagation>
        <div class="modal-header">
          <h3>新建材料分类</h3>
          <button class="close-btn" on:click={() => showCreateCategory = false}>×</button>
        </div>
        <div class="modal-body">
          <div class="form-group">
            <label>分类名称</label>
            <input 
              type="text" 
              bind:value={newCategoryName} 
              placeholder="如: 管道、管件、阀门"
            />
          </div>
          <div class="form-actions">
            <button class="btn btn-primary" on:click={handleCreateCategory}>创建</button>
            <button class="btn btn-secondary" on:click={() => showCreateCategory = false}>取消</button>
          </div>
        </div>
      </div>
    </div>
  {/if}

  <!-- Data Display -->
  {#if isLoading}
    <div class="loading">
      <div class="spinner"></div>
      <p>加载中...</p>
    </div>
  {:else if !categoryId && viewType !== 'remaining'}
    <div class="empty-state">
      <div class="empty-icon">📋</div>
      <h3>请选择材料分类</h3>
      <p>从左侧导航树中选择一个具体的材料分类，查看详细数据</p>
      {#if viewType === 'inbound' && canCreateProject(role)}
        <button class="btn btn-primary" on:click={() => showCreateCategory = true}>
          + 新建第一个分类
        </button>
      {/if}
    </div>
  {:else}
    <!-- Data Table with Actions -->
    <div class="data-table-container">
      <table class="data-table">
        <thead>
          <tr>
            <th class="row-number-col">#</th>
            {#each columns as col}
              <th>{col.label}</th>
            {/each}
            {#if viewType !== 'remaining' && canEditCurrentRecord()}
              <th class="actions-col">操作</th>
            {/if}
          </tr>
        </thead>
        <tbody>
          {#each paginatedData as row, index}
            <tr>
              <td class="row-number">{startIndex + index}</td>
              {#each columns as col}
                <td class:highlight={col.highlight}>
                  {#if col.type === 'number'}
                    {row[col.key] ?? 0}
                  {:else if col.type === 'date'}
                    {row[col.key] ? String(row[col.key]).substring(0, 10) : '-'}
                  {:else}
                    {row[col.key] || '-'}
                  {/if}
                </td>
              {/each}
              {#if viewType !== 'remaining' && canEditCurrentRecord()}
                <td class="actions-cell">
                  <button 
                    class="btn-icon btn-edit" 
                    on:click={() => openEditModal(row)}
                    title="编辑"
                  >
                    ✏️
                  </button>
                  <button 
                    class="btn-icon btn-delete" 
                    on:click={() => handleDeleteRecord(row)}
                    title="删除"
                  >
                    🗑️
                  </button>
                </td>
              {/if}
            </tr>
          {:else}
            <tr>
              <td colspan={columns.length + (viewType !== 'remaining' && canEditCurrentRecord() ? 2 : 1)} class="empty-row">
                暂无数据
              </td>
            </tr>
          {/each}
        </tbody>
      </table>
    </div>

    <!-- Pagination -->
    {#if totalItems > 0}
      <div class="pagination">
        <div class="pagination-info">
          <span>共 {totalItems} 条，显示 {startIndex}-{endIndex} 条</span>
          <span class="page-size-select">
            每页
            <select bind:value={pageSize} on:change={() => changePageSize(pageSize)}>
              {#each pageSizeOptions as size}
                <option value={size}>{size}</option>
              {/each}
            </select>
            条
          </span>
        </div>
        
        <div class="pagination-controls">
          <button 
            class="page-btn" 
            disabled={currentPage === 1}
            on:click={() => goToPage(1)}
            title="首页"
          >
            «
          </button>
          <button 
            class="page-btn" 
            disabled={currentPage === 1}
            on:click={() => goToPage(currentPage - 1)}
            title="上一页"
          >
            ‹
          </button>
          
          {#each getVisiblePages() as page}
            {#if page === '...'}
              <span class="page-ellipsis">...</span>
            {:else}
              <button 
                class="page-btn" 
                class:active={currentPage === page}
                on:click={() => goToPage(page)}
              >
                {page}
              </button>
            {/if}
          {/each}
          
          <button 
            class="page-btn" 
            disabled={currentPage === totalPages}
            on:click={() => goToPage(currentPage + 1)}
            title="下一页"
          >
            ›
          </button>
          <button 
            class="page-btn" 
            disabled={currentPage === totalPages}
            on:click={() => goToPage(totalPages)}
            title="末页"
          >
            »
          </button>
        </div>
      </div>
    {/if}
  {/if}
</div>

<!-- Edit Modal -->
{#if showEditModal && editingRecord}
  <div class="modal-overlay" on:click={closeEditModal}>
    <div class="modal" on:click|stopPropagation>
      <div class="modal-header">
        <h3>{viewType === 'inbound' ? '编辑入库记录' : '编辑出库记录'}</h3>
        <button class="btn-close" on:click={closeEditModal}>×</button>
      </div>
      <div class="modal-body">
        <div class="edit-info">
          <p><strong>材料：</strong>{editingRecord.name}</p>
          <p><strong>规格：</strong>{editingRecord.specification}</p>
          <p><strong>材质：</strong>{editingRecord.material_type}</p>
        </div>
        <div class="form-group">
          <label>数量 *</label>
          <input 
            type="number" 
            bind:value={editFormData.quantity}
            min="0.01"
            step="0.01"
            required
          />
        </div>
        <div class="form-group">
          <label>{viewType === 'inbound' ? '入库时间' : '出库时间'} *</label>
          <input 
            type="date" 
            bind:value={editFormData.date}
            required
          />
        </div>
        <div class="form-group">
          <label>{viewType === 'inbound' ? '入库单编号' : '出库单编号'}</label>
          <input 
            type="text" 
            bind:value={editFormData.batch_no}
            maxlength="100"
          />
        </div>
        <div class="form-group">
          <label>备注</label>
          <textarea 
            bind:value={editFormData.remarks}
            rows="2"
            maxlength="500"
          ></textarea>
        </div>
      </div>
      <div class="modal-footer">
        <button class="btn btn-secondary" on:click={closeEditModal}>取消</button>
        <button class="btn btn-primary" on:click={handleSaveEdit}>保存</button>
      </div>
    </div>
  </div>
{/if}

